$size = (Get-ChildItem -Path 'C:\Windows' -Force -File -ErrorAction SilentlyContinue | Measure-Object -Property Length -Sum -ErrorAction SilentlyContinue).Sum; Get-ChildItem -Path 'C:\Windows' -Directory -Force -ErrorAction SilentlyContinue | Where-Object { $_.Name -ne 'WinSxS' } | ForEach-Object { $s = (Get-ChildItem -Path $_.FullName -Recurse -Force -File -ErrorAction SilentlyContinue | Measure-Object -Property Length -Sum -ErrorAction SilentlyContinue).Sum; $size += $s }; Write-Output ('C:\Windows (excl WinSxS): ' + [math]::Round($size/1GB,2) + ' GB')
